/*
 * A284674  0-limiting word of the morphism 0->1, 1-> 0111.
 * https://oeis.org/A284674
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: a(n) is the nth element of the 0‑limiting word generated by
   the morphism 0 → 1, 1 → 0111. The word is obtained by iteratively
   applying the morphism until it reaches length ≥ n, and the function
   returns the symbol at position n (1‑based). */
#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    /* Static cache of the word constructed so far */
    static uint8_t *word   = NULL;   /* current word */
    static size_t  len    = 0;       /* length of the word */
    static size_t  cap    = 0;       /* capacity of the allocated buffer */

    /* Initialise with the starting symbol '0' */
    if (!word)
    {
        cap = 64;
        word = (uint8_t *)malloc(cap);
        if (!word) return (seq_t)0;   /* allocation failure */
        word[0] = 0;
        len = 1;
    }

    /* Expand the word until it contains the requested index */
    while ((size_t)n > len)
    {
        /* Compute the length after one more morphism application */
        size_t new_len = 0;
        for (size_t i = 0; i < len; ++i)
            new_len += (word[i] == 0) ? 1 : 4;

        /* Allocate space for the new word */
        uint8_t *new_word = (uint8_t *)malloc(new_len);
        if (!new_word) return (seq_t)0;   /* allocation failure */

        /* Build the new word */
        size_t pos = 0;
        for (size_t i = 0; i < len; ++i)
        {
            if (word[i] == 0)
            {
                /* 0 → 1 */
                new_word[pos++] = 1;
            }
            else
            {
                /* 1 → 0111 */
                new_word[pos++] = 0;
                new_word[pos++] = 1;
                new_word[pos++] = 1;
                new_word[pos++] = 1;
            }
        }

        /* Replace the old word */
        free(word);
        word = new_word;
        len  = new_len;
    }

    /* Return the nth symbol (1‑based) */
    return (seq_t)word[(size_t)n - 1];
}
